import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';

function AnimatedNumber({ value, color, fontSize = 28 }) {
  const [display, setDisplay] = useState(value);
  useEffect(() => { setDisplay(value); }, [value]);
  return (
    <div style={{
      fontSize,
      fontWeight: 700,
      color,
      lineHeight: 1,
      transition: 'color .3s'
    }}>
      {display}
    </div>
  );
}

// Mini sparkline SVG
function Sparkline({ color }) {
  const points = "0,20 10,16 20,18 30,8 40,12 50,6 60,4";
  return (
    <svg width="60" height="28" viewBox="0 0 60 28" fill="none">
      <polyline
        points={points}
        stroke={color}
        strokeWidth="1.5"
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export default function StatsRow() {
  const { stats, wsConnected } = useApp();

  const items = [
    {
      icon:     '📷',
      iconColor:'#3b82f6',
      label:    'Cameras',
      value:    `${stats.cameras_online || 0} / ${stats.cameras_total || 0}`,
      sub:      'Online',
      subColor: '#3b82f6',
      valColor: '#fff',
      spark:    '#3b82f6',
      onClick:  null
    },
    {
      icon:     '🔍',
      iconColor:'#06b6d4',
      label:    'Total Detections',
      value:    stats.total_detections || 0,
      sub:      'Today',
      subColor: '#64748b',
      valColor: '#fff',
      spark:    null,
      onClick:  null
    },
    {
      icon:     '🚨',
      iconColor:'#ef4444',
      label:    'Active Alerts',
      value:    stats.active_alerts || 0,
      sub:      'View All',
      subColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#64748b',
      valColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#fff',
      spark:    null,
      onClick:  () => window.dispatchEvent(
        new CustomEvent('navigate', { detail: 'Alerts' })
      )
    },
    {
      icon:     null,
      iconColor: '#22c55e',
      label:    'System Status',
      value:    wsConnected ? 'Healthy' : 'Offline',
      sub:      wsConnected ? 'All Systems Operational' : 'Reconnecting...',
      subColor: '#64748b',
      valColor: wsConnected ? '#22c55e' : '#f97316',
      spark:    wsConnected ? '#22c55e' : '#f97316',
      onClick:  null,
      fontSize: 22
    },
  ];

  return (
    <div style={{
      display:             'grid',
      gridTemplateColumns: 'repeat(4,1fr)',
      borderBottom:        '1px solid #1e2d47',
      flexShrink:          0,
      gap:                 '1px',
      background:          '#1e2d47'
    }}>
      {items.map((s, i) => (
        <div key={i} style={{
          background: '#111827',
          padding:    '14px 20px',
          display:    'flex',
          alignItems: 'center',
          gap:        14,
          position:   'relative'
        }}>
          {/* Icon */}
          {s.icon && (
            <span style={{ fontSize: 28, flexShrink: 0 }}>
              {s.icon}
            </span>
          )}

          {/* Sparkline for System Status */}
          {!s.icon && s.spark && (
            <Sparkline color={s.spark} />
          )}

          {/* Info */}
          <div style={{ flex: 1 }}>
            <div style={{
              fontSize:    11,
              color:       '#94a3b8',
              marginBottom: 4
            }}>
              {s.label}
            </div>
            <AnimatedNumber
              value={s.value}
              color={s.valColor || '#fff'}
              fontSize={s.fontSize || 26}
            />
            <div
              style={{
                fontSize:   11,
                color:      s.subColor,
                marginTop:  4,
                cursor:     s.onClick ? 'pointer' : 'default',
                fontWeight: s.onClick ? 600 : 400
              }}
              onClick={s.onClick || undefined}
              onMouseEnter={e => {
                if (s.onClick) e.currentTarget.style.color = '#fff';
              }}
              onMouseLeave={e => {
                if (s.onClick) e.currentTarget.style.color = s.subColor;
              }}
            >
              {s.sub}
            </div>
          </div>

          {/* Sparkline for Cameras */}
          {s.spark && s.icon && (
            <Sparkline color={s.spark} />
          )}
        </div>
      ))}
    </div>
  );
}
